template <typename Container, typename Predicate>
bool check_all(const Container& c, Predicate p) {
    for (const auto& item : c) {
        if (!p(item)) return false;
    }
    return true;
}

struct IsPositive {
    bool operator()(int x) const {
        return x > 0;
    }
};

int data[] = {1, 2, 5};

// Predicate 1: Functor
bool r1 = check_all(data, IsPositive{});

// Predicate 2: Lambda
bool r2 = check_all(data, [](int x){ return x < 10; });

// Predicate 3: Function Pointer (Decays)
bool is_odd(int x) { return x % 2 != 0; }
bool r3 = check_all(data, is_odd);
